IF OBJECT_ID(N'XSP_DEMO_LOAD', N'P') IS NOT NULL
    DROP PROCEDURE XSP_DEMO_LOAD;
GO

CREATE PROCEDURE XSP_DEMO_LOAD
    @local DATETIME2 = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @now DATETIME2 = ISNULL(@local, CAST(GETDATE() AS DATETIME2));
    DECLARE @t DATE = CAST(@now AS DATE);
    DECLARE @k INT = DATEDIFF(DAY, CAST('19000101' AS DATE), @t) % 7;
    DECLARE @d DATE = DATEADD(DAY, -@k, @t);
    DECLARE @d0 DATETIME2 = CAST(@d AS DATETIME2);
    DECLARE @nowu DATETIME2 = SYSUTCDATETIME();
    DECLARE @z0 DATETIME2 = DATEADD(MINUTE, CAST(ROUND(DATEDIFF(SECOND, @now, @nowu) / 900.0, 0) AS INT) * 15, @d0);
    DECLARE @hm INT = DATEPART(HOUR, @now) * 60 + DATEPART(MINUTE, @now);
    DECLARE @open INT = CASE @k WHEN 6 THEN -1 WHEN 0 THEN 450 WHEN 1 THEN 450 WHEN 2 THEN 450 WHEN 3 THEN 450 WHEN 4 THEN 450 WHEN 5 THEN 480 END;
    DECLARE @close INT = CASE @k WHEN 6 THEN -1 WHEN 0 THEN 1140 WHEN 1 THEN 1140 WHEN 2 THEN 1140 WHEN 3 THEN 1140 WHEN 4 THEN 1140 WHEN 5 THEN 960 END;
    DECLARE @gone TABLE (APPT_ID NVARCHAR(50), VISIT_ID NVARCHAR(50));
    DECLARE @live TABLE (VISIT_ID NVARCHAR(50), APPT_ID NVARCHAR(50), NEED_BEFORE INT, NEED_AFTER INT, STAFF_ID NVARCHAR(50), BUSY_FROM DATETIME2, BUSY_TO DATETIME2);
    BEGIN TRANSACTION;
    DELETE FROM ACTIVITY;
    DELETE FROM MAILLOG;
    DELETE FROM PAYMENT;
    DELETE FROM INVOICELINE;
    DELETE FROM INVOICE;
    DELETE FROM VISITFILE;
    DELETE FROM RESULT;
    DELETE FROM ORDERLINE;
    DELETE FROM DIAGNOSIS;
    DELETE FROM VISITNOTE;
    DELETE FROM VISITROOM;
    DELETE FROM VISIT;
    DELETE FROM APPTLOG;
    DELETE FROM APPOINTMENT;
    DELETE FROM REMINDER;
    DELETE FROM PETVACCINE;
    DELETE FROM PETWEIGHT;
    DELETE FROM PET;
    DELETE FROM CLIENT;
    DELETE FROM HOLIDAY;
    DELETE FROM BOOKSTAFF;
    DELETE FROM BOOKTYPE;
    DELETE FROM TIMEOFF;
    DELETE FROM STAFFHOURS;
    DELETE FROM STAFFSPECIES;
    DELETE FROM STAFFPERM;
    DELETE FROM STAFF;
    DELETE FROM ROOM;
    DELETE FROM ROOMTYPE;
    DELETE FROM TESTFIELD;
    DELETE FROM ITEM;
    DELETE FROM TEAM;
    DELETE FROM PAGEVER;
    DELETE FROM PAGEDOC;
    DELETE FROM ALBUMITEM;
    DELETE FROM ALBUM;
    DELETE FROM MEDIA;
    DELETE FROM MESSAGE;
    DELETE FROM NUMBERSEQ;
    UPDATE SETTING SET SVALUE = N'Chance Animal Hospital', SYSDTE = GETDATE() WHERE SKEY = N'name';
