    DELETE FROM @live WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone);
    DELETE FROM RESULT WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM ORDERLINE WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM DIAGNOSIS WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM VISITNOTE WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM VISITROOM WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM PETWEIGHT WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM PETVACCINE WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM PAYMENT WHERE INVOICE_ID IN (SELECT INVOICE_ID FROM INVOICE WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N''));
    DELETE FROM INVOICE WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM VISIT WHERE VISIT_ID IN (SELECT VISIT_ID FROM @gone WHERE VISIT_ID <> N'');
    DELETE FROM APPTLOG WHERE APPT_ID IN (SELECT APPT_ID FROM @gone);
    DELETE FROM APPOINTMENT WHERE APPT_ID IN (SELECT APPT_ID FROM @gone);
    UPDATE ORDERLINE SET STATUS = N'ordered', DONE_BY = N'', DONE_UTC = NULL WHERE ITEM_TYPE = N'test' AND RIGHT(VISIT_ID, 1) IN (N'1', N'4', N'7') AND VISIT_ID IN (SELECT VISIT_ID FROM VISIT WHERE CHECKIN_AT >= DATEADD(DAY, -2, CAST(@t AS DATETIME2)) AND CHECKIN_AT <= @now AND STATUS IN (N'closed', N'checkout', N'inroom'));
    DELETE FROM RESULT WHERE LINE_ID IN (SELECT LINE_ID FROM ORDERLINE WHERE ITEM_TYPE = N'test' AND STATUS = N'ordered');
    UPDATE VISITNOTE SET SIGNED_BY = STAFF_ID WHERE SIGNED_UTC IS NOT NULL;
    UPDATE VISIT SET VISIT_NO = N'V' + CAST(YEAR(CHECKIN_AT) AS NVARCHAR(4)) + RIGHT(VISIT_NO, 6);
    UPDATE INVOICE SET INVOICE_NO = N'INV' + CAST(YEAR(CREATED_UTC) AS NVARCHAR(4)) + RIGHT(INVOICE_NO, 6);
    UPDATE PAYMENT SET PAY_NO = N'PAY' + CAST(YEAR(PAID_UTC) AS NVARCHAR(4)) + RIGHT(PAY_NO, 6);
    SELECT I.INVOICE_ID + N'-' + CAST(O.LINE_ORDER AS NVARCHAR(10)), I.INVOICE_ID, O.LINE_ID, O.ITEM_ID, O.ITEM_TYPE, O.ITEM_NAME, O.QTY, O.UNIT_PRICE, O.TAXABLE, ROUND(O.QTY * O.UNIT_PRICE, 2), O.LINE_ORDER
    FROM INVOICE I JOIN ORDERLINE O ON O.VISIT_ID = I.VISIT_ID WHERE O.STATUS <> N'cancelled';
    UPDATE INVOICE SET SUBTOTAL = X.S, TOTAL = X.S - DISCOUNT, BALANCE = X.S - DISCOUNT - PAID FROM INVOICE JOIN (SELECT INVOICE_ID, SUM(AMOUNT) AS S FROM INVOICELINE GROUP BY INVOICE_ID) X ON X.INVOICE_ID = INVOICE.INVOICE_ID WHERE INVOICE.STATUS = N'open';
    UPDATE SETTING SET SVALUE = CONVERT(NVARCHAR(10), @t, 23), SYSDTE = GETDATE() WHERE SKEY = N'demo.day';
    IF @@ROWCOUNT = 0 INSERT INTO SETTING (SKEY, SVALUE) VALUES (N'demo.day', CONVERT(NVARCHAR(10), @t, 23));
    COMMIT TRANSACTION;
END
GO

