    INSERT INTO PAGEDOC (PAGE_KEY, BLOCKS, SAVED_UTC, SAVED_BY) VALUES
    (N'home', N'[{"id": "b100007", "type": "hero", "source": "", "hidden": false, "kicker": "{town} · caring for pets since 2009", "title": "Good care takes time. We make the time.", "text": "<p>Exams, vaccines, dentistry and surgery for dogs, cats and exotic pets, plus grooming and boarding under one roof. Book online in a minute.</p>", "media": "images/hospital/full/exterior.webp", "label": "Book a visit", "link": "Book", "label2": "Book a boarding stay", "link2": "BookStay", "flip": false, "extra": "finder", "items": []}, {"id": "b100014", "type": "data", "source": "teams", "hidden": false, "kicker": "What we do", "title": "Care for every stage of life", "text": "<p>Pick a team to see its services and the next free time online.</p>", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100021", "type": "cards", "source": "", "hidden": false, "kicker": "New here?", "title": "Your first visit in three steps", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": [{"icon": "cal", "media": "", "title": "Book online", "text": "Choose a service and a time that suits you. No account needed.", "link": "Book", "label": "Find a time"}, {"icon": "doc", "media": "", "title": "Fill in the form", "text": "Download the new client form, or fill it in at the desk when you arrive.", "link": "Media", "label": "Get the form"}, {"icon": "paw", "media": "", "title": "Meet the team", "text": "Arrive ten minutes early. We weigh your pet and bring you into a quiet room.", "link": "PetOwners", "label": "What to expect"}]}, {"id": "b100028", "type": "data", "source": "vets", "hidden": false, "kicker": "Our team", "title": "Meet the vets", "text": "<p>Five vets, a technician and two groomers who know your pet by name.</p>", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100035", "type": "split", "source": "", "hidden": false, "kicker": "Cats only", "title": "A quiet room just for cats", "text": "<p>Our cat room is on the far side of the building, away from barking. Dr. Raman sees cats only, with low lights, warm towels and no rush.</p>", "media": "images/hospital/full/cat-room.webp", "label": "Book a cat visit", "link": "Book?t=wellness", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100042", "type": "data", "source": "boardband", "hidden": false, "kicker": "Boarding", "title": "A safe, happy stay while you''re away", "text": "<p>Roomy dog runs, cat condos with a view and a vet on site every day.</p>", "media": "", "label": "See runs and prices", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100049", "type": "stats", "source": "", "hidden": false, "kicker": "In numbers", "title": "Small-town hospital, full service", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": [{"icon": "", "media": "", "title": "17", "text": "Years in Larkspur Falls", "link": "", "label": ""}, {"icon": "", "media": "", "title": "6", "text": "Kinds of pets we see", "link": "", "label": ""}, {"icon": "", "media": "", "title": "Same day", "text": "Sick visits every weekday", "link": "", "label": ""}, {"icon": "", "media": "", "title": "24/7", "text": "Emergency partner nearby", "link": "", "label": ""}]}, {"id": "b100056", "type": "data", "source": "hours", "hidden": false, "kicker": "Visit us", "title": "Hours and directions", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}]', DATEADD(MINUTE, -13800, @z0), N's-rowan'),
    (N'services', N'[{"id": "b100063", "type": "hero", "source": "", "hidden": false, "kicker": "Services", "title": "Everything your pet needs, in one place", "text": "<p>Every service with its length, price and the next free time online. Prices are a guide; your vet confirms before any treatment.</p>", "media": "images/hospital/full/exam-room.webp", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100070", "type": "data", "source": "servicelist", "hidden": false, "kicker": "", "title": "All services", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100077", "type": "cta", "source": "", "hidden": false, "kicker": "Not sure what to book?", "title": "Call us and we''ll help you choose", "text": "<p>Tell us what is going on and we''ll find the right visit and the right vet.</p>", "media": "", "label": "Contact us", "link": "Contact", "label2": "Book a sick visit", "link2": "Book?sv=sick-visit", "flip": false, "extra": "", "items": []}]', DATEADD(MINUTE, -13800, @z0), N's-rowan'),
    (N'vets', N'[{"id": "b100084", "type": "hero", "source": "", "hidden": false, "kicker": "Our team", "title": "Vets, a technician and groomers who know your pet", "text": "<p>Every vet lists the animals they see. Pick one, or choose First available when you book.</p>", "media": "images/hospital/full/reception.webp", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100091", "type": "data", "source": "vetlist", "hidden": false, "kicker": "", "title": "The team", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}]', DATEADD(MINUTE, -13800, @z0), N's-rowan'),
    (N'boarding', N'[{"id": "b100098", "type": "hero", "source": "", "hidden": false, "kicker": "Boarding", "title": "A stay that feels like a holiday", "text": "<p>Dog runs sized for your dog, cat condos away from the barking, three walks a day and a vet on site every day.</p>", "media": "images/hospital/full/dog-runs.webp", "label": "Book a stay", "link": "BookStay", "label2": "See a day in boarding", "link2": "Media", "flip": false, "extra": "", "items": []}, {"id": "b100105", "type": "data", "source": "runlist", "hidden": false, "kicker": "Runs and prices", "title": "Choose the right room", "text": "<p>Prices are per night. Check-in from 7:30 am, check-out by 11 am.</p>", "media": "", "label": "Book a stay", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100112", "type": "data", "source": "vaxrules", "hidden": false, "kicker": "Before you book", "title": "Vaccines needed for boarding", "text": "<p>For everyone''s safety, these vaccines must be valid until the day you pick up. We can give them at a vaccine visit before the stay.</p>", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100119", "type": "faq", "source": "", "hidden": false, "kicker": "Questions", "title": "Boarding questions", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": [{"icon": "", "media": "", "title": "Can I bring my dog''s own food?", "text": "Yes, please do. Label it with your pet''s name and how much to feed.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "Can two pets share a run?", "text": "Pets from the same home can share a run or a condo if they get along. Book one stay per pet and add a note.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "What if my pet gets sick?", "text": "A vet sees them the same day and we call you before any treatment.", "link": "", "label": ""}]}]', DATEADD(MINUTE, -13800, @z0), N's-rowan'),
    (N'petowners', N'[{"id": "b100126", "type": "hero", "source": "", "hidden": false, "kicker": "For pet owners", "title": "Before, during and after your visit", "text": "<p>What to bring, how we keep visits calm, vaccines, pet insurance and the questions we hear most.</p>", "media": "images/hospital/full/reception.webp", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100133", "type": "steps", "source": "", "hidden": false, "kicker": "First visit", "title": "What happens at your first visit", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": [{"icon": "", "media": "", "title": "Check-in", "text": "Arrive ten minutes early with records from your last vet.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "Weight and history", "text": "Our technician weighs your pet and asks about food, habits and medicines.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "Exam", "text": "Your vet does a full exam and talks you through what they find.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "Plan and pay", "text": "You leave with a written plan, a receipt for your insurance and your next visit booked if you like.", "link": "", "label": ""}]}, {"id": "b100140", "type": "split", "source": "", "hidden": false, "kicker": "Fear Free visits", "title": "Fewer nerves, more treats", "text": "<p>We go slow, use treats and soft mats, and let nervous pets settle before we start. Tell us if your pet has had a hard time at the vet before.</p>", "media": "images/hospital/full/exam-room.webp", "label": "", "link": "", "label2": "", "link2": "", "flip": true, "extra": "", "items": []}, {"id": "b100147", "type": "data", "source": "vaxchart", "hidden": false, "kicker": "Vaccines", "title": "Vaccine schedule", "text": "<p>A guide to the vaccines we recommend. Your vet will tailor the plan to your pet''s age and lifestyle.</p>", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100154", "type": "data", "source": "insurance", "hidden": false, "kicker": "Paying for care", "title": "Pet insurance and payment", "text": "<p>We take card, cash and tap, and give you an itemised receipt to send to your insurer.</p>", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100161", "type": "faq", "source": "", "hidden": false, "kicker": "Questions", "title": "Questions we hear most", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": [{"icon": "", "media": "", "title": "Do I need an appointment for a sick pet?", "text": "Please call or book a sick visit online. We keep time free every day for pets who need to be seen today.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "What should I bring to the first visit?", "text": "Your pet on a lead or in a carrier, any records from your last vet, a list of food and medicines, and a stool sample if you can.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "How do I pay?", "text": "Card, cash or tap at the end of the visit. We give you an itemised receipt to send to your pet insurance.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "Can I stay with my pet?", "text": "Yes, for exams. For surgery and dental cleanings your pet stays with our team and we call you when they are awake.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "What vaccines are needed for boarding?", "text": "Dogs need rabies, DHPP and Bordetella. Cats need rabies and FVRCP. They must be valid until the day you pick up.", "link": "", "label": ""}, {"icon": "", "media": "", "title": "How do I change or cancel?", "text": "Use My appointment with your booking code. Visits can be changed for free up to 24 hours before; boarding up to 48 hours before.", "link": "", "label": ""}]}]', DATEADD(MINUTE, -13800, @z0), N's-rowan'),
    (N'emergency', N'[{"id": "b100168", "type": "hero", "source": "", "hidden": false, "kicker": "Emergency", "title": "Is your pet in trouble right now?", "text": "<p>Call us first during opening hours. When we are closed, go to the 24-hour emergency hospital below. Do not wait for an online booking.</p>", "media": "images/hospital/full/surgery-suite.webp", "label": "Call the hospital", "link": "tel:5550142200", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100175", "type": "data", "source": "urgent", "hidden": false, "kicker": "Who to call", "title": "Call before you come in", "text": "<p>Calling ahead lets the team get ready for your pet.</p>", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100182", "type": "cards", "source": "", "hidden": false, "kicker": "Signs of an emergency", "title": "Call right away if your pet", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": [{"icon": "heart", "media": "", "title": "Has trouble breathing", "text": "Open-mouth breathing in a cat, blue gums, or choking.", "link": "", "label": ""}, {"icon": "shield", "media": "", "title": "Ate something toxic", "text": "Chocolate, grapes, lilies (cats), xylitol gum, rat bait or human medicines. Bring the packet.", "link": "", "label": ""}, {"icon": "clock", "media": "", "title": "Collapsed or had a seizure", "text": "Or cannot stand, or is suddenly very weak.", "link": "", "label": ""}, {"icon": "paw", "media": "", "title": "Has a swollen belly", "text": "Especially a large dog trying to vomit with nothing coming up.", "link": "", "label": ""}, {"icon": "check", "media": "", "title": "Cannot pee", "text": "A cat straining in the litter box with little or no urine.", "link": "", "label": ""}, {"icon": "star", "media": "", "title": "Was hit by a car", "text": "Even if they seem fine, there can be injuries you cannot see.", "link": "", "label": ""}]}, {"id": "b100189", "type": "text", "source": "", "hidden": false, "kicker": "Please note", "title": "This page is not medical advice", "text": "<p>It lists common warning signs only. If you are worried about your pet, call a vet.</p>", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}]', DATEADD(MINUTE, -13800, @z0), N's-rowan'),
    (N'media', N'[{"id": "b100196", "type": "hero", "source": "", "hidden": false, "kicker": "Media", "title": "Photos, videos and forms", "text": "<p>Take a look around the hospital, watch a day in boarding and download our forms before your visit.</p>", "media": "images/hospital/full/lab.webp", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100203", "type": "data", "source": "albums", "hidden": false, "kicker": "Albums", "title": "Photo albums", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100210", "type": "data", "source": "videos", "hidden": false, "kicker": "Videos", "title": "Watch", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100217", "type": "data", "source": "docs", "hidden": false, "kicker": "Documents", "title": "Forms and guides", "text": "", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}]', DATEADD(MINUTE, -13800, @z0), N's-rowan'),
    (N'contact', N'[{"id": "b100224", "type": "hero", "source": "", "hidden": false, "kicker": "Contact", "title": "Come and see us", "text": "<p>Free parking on Orchard Lane, a short walk from the 12 bus. Call, book online or send us a message.</p>", "media": "images/hospital/full/exterior.webp", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}, {"id": "b100231", "type": "data", "source": "contact", "hidden": false, "kicker": "Get in touch", "title": "Hours, directions and messages", "text": "<p>For anything urgent, please call. Messages are read during opening hours.</p>", "media": "", "label": "", "link": "", "label2": "", "link2": "", "flip": false, "extra": "", "items": []}]', DATEADD(MINUTE, -13800, @z0), N's-rowan');
