    INSERT INTO STAFFPERM (STAFF_ID, MENU_KEY, RIGHTS) SELECT S.STAFF_ID, P.MENU_KEY, P.RIGHTS FROM STAFF S JOIN ROLEPERM P ON P.ROLE_ID = S.ROLE_ID WHERE S.IS_DEMO = 1;
