    INSERT INTO @gone (APPT_ID, VISIT_ID) SELECT APPT_ID, VISIT_ID FROM @live L WHERE @open < 0 OR @hm - @open < NEED_BEFORE OR @close - @hm < NEED_AFTER OR EXISTS (SELECT 1 FROM HOLIDAY H WHERE H.HOLIDAY_DATE = @t) OR NOT EXISTS (SELECT 1 FROM STAFFHOURS H WHERE H.STAFF_ID = L.STAFF_ID AND H.DAY_NO = (@k + 1) % 7 AND H.IS_ON = 1) OR EXISTS (SELECT 1 FROM TIMEOFF T WHERE T.STAFF_ID = L.STAFF_ID AND T.FROM_DATE <= @t AND T.TO_DATE >= @t);
    INSERT INTO @gone (APPT_ID, VISIT_ID) SELECT A.APPT_ID, A.VISIT_ID FROM APPOINTMENT A WHERE A.APPT_ID LIKE N'%A' AND A.VISIT_TYPE <> N'boarding' AND (ISNULL(A.PICKUP_AT, A.END_AT) > DATEADD(MINUTE, -10, @now) OR EXISTS (SELECT 1 FROM @live L WHERE L.STAFF_ID = A.STAFF_ID AND L.BUSY_FROM < ISNULL(A.PICKUP_AT, A.END_AT) AND L.BUSY_TO > A.START_AT));
    INSERT INTO @gone (APPT_ID, VISIT_ID) SELECT A.APPT_ID, A.VISIT_ID FROM APPOINTMENT A WHERE A.APPT_ID LIKE N'%B' AND A.VISIT_TYPE <> N'boarding' AND (A.START_AT < DATEADD(MINUTE, 15, @now) OR (A.PROC_AT IS NOT NULL AND A.PROC_AT < DATEADD(MINUTE, 90, @now)) OR EXISTS (SELECT 1 FROM @live L WHERE L.STAFF_ID = A.STAFF_ID AND L.BUSY_FROM < ISNULL(A.PROC_AT, A.END_AT) AND L.BUSY_TO > ISNULL(A.PROC_AT, A.START_AT)));
    INSERT INTO @gone (APPT_ID, VISIT_ID) SELECT A.APPT_ID, A.VISIT_ID FROM APPOINTMENT A WHERE A.VISIT_TYPE = N'boarding' AND ((A.APPT_ID LIKE N'%A' AND A.END_AT > @now) OR (A.APPT_ID LIKE N'%C' AND (DATEADD(MINUTE, 10, A.START_AT) > @now OR A.END_AT <= @now)) OR (A.APPT_ID LIKE N'%B' AND A.START_AT <= @now));
    INSERT INTO INVOICELINE (ILINE_ID, INVOICE_ID, LINE_ID, ITEM_ID, ITEM_TYPE, DESCRIPTION, QTY, UNIT_PRICE, TAXABLE, AMOUNT, LINE_ORDER)
    INSERT INTO NUMBERSEQ (SEQ_KEY, SEQ_YEAR, SEQ_VALUE) VALUES (N'VIS', YEAR(GETDATE()), 1374), (N'INV', YEAR(GETDATE()), 1339), (N'PAY', YEAR(GETDATE()), 1305), (N'CLI', YEAR(GETDATE()), 1654);
